compare-jfr.py.content:
import collections
import datetime
import json
import pathlib
import re

base = pathlib.Path(__file__).resolve().parent


def timestamp(value):
    return datetime.datetime.fromisoformat(value.replace('Z', '+00:00')).timestamp()


def duration(value):
    match = re.fullmatch(r'PT(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?', value)
    assert match, value
    return sum(float(x or 0) * scale for x, scale in zip(match.groups(), [3600, 60, 1]))


def matchweight(path, needles):
    return sum(int(line.rsplit(' ', 1)[1]) for line in path.read_text().splitlines()
               if all(needle in line for needle in needles))


report = {}
settings = {}
for name, out in [('baseline', 'jfr-analysis'), ('optimized', 'optimized-jfr-analysis')]:
    data = json.loads((base / out / 'summary.json').read_text())
    window = data['selectedWindow']
    start, end = timestamp(window['start']), timestamp(window['end'])
    result = {'window': window, 'benchmarkMeasuredSeconds': data['benchmarkMeasuredSeconds'],
              'windowMinusBenchmarkSeconds': data['windowMinusBenchmarkSeconds'], 'metrics': {},
              'durationsSeconds': {a['name']: a['weight'] / 1e9 for a in data['clippedDurationNanosByEventCategory']},
              'durationEventCounts': data['durationEventCounts']}
    for kind, metric in data['sampleMetrics'].items():
        categories = {item['name']: item['weight'] for item in metric['categories']}
        result['metrics'][kind] = {'events': metric['events'], 'weight': metric['weight'],
            'categories': categories, 'categoryPercent': {k: v / metric['weight'] * 100 for k, v in categories.items()},
            'leafFrames': metric['leafFrames'][:15]}
    result['hostStageConcatenateAllocBytes'] = matchweight(base / out / 'jdk.ObjectAllocationSample.folded',
        ['CfrInferenceWorkspace.stage', 'DecisionHostBatch.concatenate', 'DecisionHostInputs.<init>'])
    result['hostStageConcatenateJavaSamples'] = matchweight(base / out / 'jdk.ExecutionSample.folded',
        ['CfrInferenceWorkspace.stage', 'DecisionHostBatch.concatenate'])
    events = json.loads((base / out / 'gc-settings-events.json').read_text())['recording']['events']
    event_types = json.loads((base / out / 'event-types.json').read_text())
    settings[name] = sorted(set((event_types[str(e['values']['id'])], e['values']['name'], e['values']['value'])
        for e in events if e['type'] == 'jdk.ActiveSetting'))
    gc = {'phasePauseCount': 0, 'phasePauseClippedSeconds': 0, 'phasePauseMaxSeconds': 0,
          'pauseByName': {}, 'garbageCollectionCount': 0, 'gcCpuUserSeconds': 0,
          'gcCpuSystemSeconds': 0, 'gcCpuRealSeconds': 0, 'dataLossEvents': 0}
    for event in events:
        value = event['values']
        time = timestamp(value['startTime'])
        if event['type'] == 'jdk.GCPhasePause':
            clipped = max(0, min(end, time + duration(value['duration'])) - max(start, time))
            if clipped:
                gc['phasePauseCount'] += 1
                gc['phasePauseClippedSeconds'] += clipped
                gc['phasePauseMaxSeconds'] = max(gc['phasePauseMaxSeconds'], clipped)
                item = gc['pauseByName'].setdefault(value['name'], {'count': 0, 'seconds': 0})
                item['count'] += 1
                item['seconds'] += clipped
        elif start <= time <= end:
            if event['type'] == 'jdk.GarbageCollection':
                gc['garbageCollectionCount'] += 1
            if event['type'] == 'jdk.GCCPUTime':
                for key, field in [('gcCpuUserSeconds', 'userTime'), ('gcCpuSystemSeconds', 'systemTime'), ('gcCpuRealSeconds', 'realTime')]:
                    gc[key] += duration(value[field])
            if event['type'] == 'jdk.DataLoss':
                gc['dataLossEvents'] += 1
    result['gc'] = gc
    report[name] = result

report['sameActiveSettings'] = settings['baseline'] == settings['optimized']
report['activeSettingDifferences'] = {'baselineOnly': sorted(set(settings['baseline']) - set(settings['optimized'])),
    'optimizedOnly': sorted(set(settings['optimized']) - set(settings['baseline']))}
report['sampleSettings'] = [item for item in settings['baseline'] if item[0] in
    ['jdk.ExecutionSample', 'jdk.NativeMethodSample', 'jdk.ObjectAllocationSample', 'jdk.GCPhasePause']]
report['limitations'] = ('JFR sampling is statistical, not CPU/GPU time. Allocation weights estimate Java heap allocated bytes, '
    'not retained heap. Same main rows; asynchronous branch counts differ slightly. Top-level GCPhasePause durations are '
    'clipped to the writer lifetime; other GC durations may include concurrent phases. Warmup/setup/post-run decode excluded. '
    'Profile run rates are separate from unprofiled benchmark rates. Timestamp clipping uses microsecond-resolution datetime.')
(base / 'jfr-comparison.json').write_text(json.dumps(report, indent=2) + '\n')
for name in ['baseline', 'optimized']:
    result = report[name]
    print(name, 'duration', result['benchmarkMeasuredSeconds'], 'concat_alloc', result['hostStageConcatenateAllocBytes'],
          'concat_cpu', result['hostStageConcatenateJavaSamples'])
    print('GC', json.dumps(result['gc']))
    for kind, metric in result['metrics'].items():
        print(kind, 'total', metric['weight'], 'categories', json.dumps(metric['categories']))
        print('TOP', json.dumps(metric['leafFrames'][:7]))
print('sameActiveSettings', report['sameActiveSettings'])
print('diff', json.dumps(report['activeSettingDifferences']))

jfr-helper/AnalyzeCollectorJfr.java.content:
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import jdk.jfr.consumer.RecordedEvent;
import jdk.jfr.consumer.RecordedThread;
import jdk.jfr.consumer.RecordingFile;

/** writerの寿命で測定窓を識別し、収集後の復号を除外してJFRを集計する一時解析器。 */
public final class AnalyzeCollectorJfr {
  private static final String WRITER = "cfr-episode-writer-";

  private record Lifetime(long id, String name, Instant start, Instant end) {}

  private record Window(Instant start, Instant end, List<Lifetime> writers) {
    double seconds() {
      return Duration.between(start, end).toNanos() / 1e9;
    }

    boolean contains(Instant time) {
      return !time.isBefore(start) && !time.isAfter(end);
    }
  }

  public static void main(String[] args) throws Exception {
    if (args.length == 1 && args[0].equals("--self-test")) {
      selfTest();
      return;
    }
    if (args.length < 2 || args.length > 3)
      throw new IllegalArgumentException("INPUT.jfr OUTPUT_DIR [REPORT_MEASURED_SECONDS]");
    Path input = Path.of(args[0]);
    Path output = Path.of(args[1]);
    List<Window> windows = windows(input);
    if (windows.isEmpty()) throw new IOException("No complete four-writer collection window");
    Window selected = windows.getLast();
    Map<String, Object> report = new LinkedHashMap<>();
    report.put("input", input.toAbsolutePath().toString());
    report.put("selectedWindow", window(selected));
    report.put("allWindows", windows.stream().map(AnalyzeCollectorJfr::window).toList());
    if (args.length == 3) {
      double expected = Double.parseDouble(args[2]);
      double delta = selected.seconds() - expected;
      report.put("benchmarkMeasuredSeconds", expected);
      report.put("windowMinusBenchmarkSeconds", delta);
      if (!(expected > 0) || Math.abs(delta) > Math.max(0.25, expected * 0.02))
        throw new IOException("Writer lifetime does not match benchmark duration: " + delta);
    }
    report.put(
        "windowScope",
        "Last complete group of four cfr-episode-writer threads, from first ThreadStart to last"
            + " ThreadEnd. This approximates the measured collection interval within thread startup"
            + " and join/report bookkeeping; it excludes subsequent observation decoding. Compare"
            + " against the measured seconds from THIS profiled run, not an unprofiled run.");
    report.put(
        "limitations",
        "ExecutionSample and NativeMethodSample counts are separate statistical samples, not CPU"
            + " seconds or GPU kernel time. Native samples may include JNI/event polling or"
            + " blocking calls. ObjectAllocationSample.weight estimates allocated Java-heap bytes;"
            + " it is not exact object size, live/retained heap, RSS, direct memory or device"
            + " allocation. Inclusive frame counts overlap. Allocation sampled weights can straddle"
            + " the selected window. Duration events are clipped to the window and summed across"
            + " threads; summed durations can exceed wall time. File events include only configured"
            + " threshold hits.");
    Map<String, Samples> samples = new LinkedHashMap<>();
    samples.put("jdk.ExecutionSample", new Samples(false));
    samples.put("jdk.NativeMethodSample", new Samples(false));
    samples.put("jdk.ObjectAllocationSample", new Samples(true));
    Map<String, Long> seen = new HashMap<>(), outside = new HashMap<>();
    Map<String, Long> durations = new HashMap<>(), durationCounts = new HashMap<>();
    try (var recording = new RecordingFile(input)) {
      while (recording.hasMoreEvents()) {
        RecordedEvent event = recording.readEvent();
        String type = event.getEventType().getName();
        seen.merge(type, 1L, Long::sum);
        Samples metric = samples.get(type);
        if (metric != null) {
          if (!selected.contains(event.getStartTime())) {
            outside.merge(type, 1L, Long::sum);
            continue;
          }
          RecordedThread thread =
              event.hasField("sampledThread")
                  ? event.getThread("sampledThread")
                  : event.getThread();
          List<String> stack = stack(event);
          String name = threadName(thread);
          long weight = metric.allocation ? event.getLong("weight") : 1;
          String object = metric.allocation ? event.getClass("objectClass").getName() : "";
          metric.add(name, stack, weight, object);
        } else if (type.equals("jdk.ThreadPark")
            || type.equals("jdk.JavaMonitorWait")
            || type.equals("jdk.JavaMonitorEnter")
            || type.equals("jdk.FileWrite")
            || type.equals("jdk.FileForce")
            || type.equals("jdk.GarbageCollection")) {
          Instant start =
              event.getStartTime().isBefore(selected.start) ? selected.start : event.getStartTime();
          Instant end =
              event.getEndTime().isAfter(selected.end) ? selected.end : event.getEndTime();
          if (!end.isAfter(start)) continue;
          RecordedThread thread = event.getThread();
          String name = threadName(thread);
          String key = type + " | " + category(name, stack(event));
          durations.merge(key, Duration.between(start, end).toNanos(), Long::sum);
          durationCounts.merge(key, 1L, Long::sum);
        }
      }
    }
    report.put("recordingEventCounts", seen);
    report.put("excludedOutOfWindowSamples", outside);
    report.put(
        "sampleMetrics",
        samples.entrySet().stream()
            .collect(
                LinkedHashMap::new,
                (map, entry) -> map.put(entry.getKey(), entry.getValue().summary()),
                Map::putAll));
    report.put("clippedDurationNanosByEventCategory", top(durations, 100));
    report.put("durationEventCounts", durationCounts);
    Files.createDirectories(output);
    Files.writeString(output.resolve("summary.json"), json(report) + "\n");
    for (var entry : samples.entrySet())
      Files.writeString(output.resolve(entry.getKey() + ".folded"), entry.getValue().folded());
    System.out.println(
        "Window " + selected.start + " .. " + selected.end + " (" + selected.seconds() + " s)");
    for (var entry : samples.entrySet())
      System.out.println(
          entry.getKey()
              + " events="
              + entry.getValue().events
              + " weight="
              + entry.getValue().weight);
  }

  private static Map<String, Object> window(Window window) {
    return Map.of(
        "start",
        window.start.toString(),
        "end",
        window.end.toString(),
        "seconds",
        window.seconds(),
        "writers",
        window.writers.stream()
            .map(
                life ->
                    Map.of(
                        "id",
                        life.id,
                        "name",
                        life.name,
                        "start",
                        life.start.toString(),
                        "end",
                        life.end.toString()))
            .toList());
  }

  private static List<Window> windows(Path path) throws IOException {
    Map<Long, Lifetime> lives = new HashMap<>();
    try (var recording = new RecordingFile(path)) {
      while (recording.hasMoreEvents()) {
        RecordedEvent event = recording.readEvent();
        String type = event.getEventType().getName();
        if (!type.equals("jdk.ThreadStart") && !type.equals("jdk.ThreadEnd")) continue;
        RecordedThread thread =
            event.hasField("thread") ? event.getThread("thread") : event.getThread();
        if (thread == null || !threadName(thread).startsWith(WRITER)) continue;
        long id = thread.getJavaThreadId();
        Lifetime previous = lives.get(id);
        Instant start =
            type.equals("jdk.ThreadStart")
                ? event.getStartTime()
                : previous == null ? null : previous.start;
        Instant end =
            type.equals("jdk.ThreadEnd")
                ? event.getStartTime()
                : previous == null ? null : previous.end;
        lives.put(id, new Lifetime(id, threadName(thread), start, end));
      }
    }
    return group(lives.values().stream().toList());
  }

  private static List<Window> group(List<Lifetime> lives) throws IOException {
    List<Window> result = new ArrayList<>();
    List<List<Lifetime>> lanes = new ArrayList<>();
    for (int lane = 0; lane < 4; lane++) {
      String name = WRITER + lane;
      lanes.add(
          lives.stream()
              .filter(life -> life.name.equals(name))
              .filter(life -> life.start != null && life.end != null)
              .sorted(Comparator.comparing(Lifetime::start))
              .toList());
    }
    int groups = lanes.getFirst().size();
    for (var lane : lanes)
      if (lane.size() != groups) throw new IOException("Incomplete writer groups");
    for (int index = 0; index < groups; index++) {
      List<Lifetime> writers = new ArrayList<>();
      for (var lane : lanes) writers.add(lane.get(index));
      Instant firstStart =
          writers.stream().map(Lifetime::start).min(Instant::compareTo).orElseThrow();
      Instant lastStart =
          writers.stream().map(Lifetime::start).max(Instant::compareTo).orElseThrow();
      Instant firstEnd = writers.stream().map(Lifetime::end).min(Instant::compareTo).orElseThrow();
      Instant lastEnd = writers.stream().map(Lifetime::end).max(Instant::compareTo).orElseThrow();
      if (!firstEnd.isAfter(lastStart))
        throw new IOException("Writer group lifetimes do not overlap");
      result.add(new Window(firstStart, lastEnd, List.copyOf(writers)));
    }
    return result;
  }

  private static List<String> stack(RecordedEvent event) {
    if (event.getStackTrace() == null) return List.of();
    return event.getStackTrace().getFrames().stream()
        .map(frame -> frame.getMethod().getType().getName() + "." + frame.getMethod().getName())
        .toList();
  }

  private static String threadName(RecordedThread thread) {
    if (thread == null) return "<unknown>";
    if (thread.getJavaName() != null) return thread.getJavaName();
    return thread.getOSName() == null ? "<unnamed>" : thread.getOSName();
  }

  private static String category(String thread, List<String> frames) {
    String stack = String.join("\n", frames);
    if (stack.contains("CfrObservationCodec.decode") || stack.contains("CfrMatchFile.read"))
      return "observation_decode";
    if (stack.contains("CfrObservationCodec.encode")
        || stack.contains("DecisionInputRowCodec.write")) return "observation_serialization";
    if (thread.startsWith(WRITER) || stack.contains("CfrBinaryCodec.writeCompressedEpisode"))
      return "episode_persistence";
    if (stack.contains("CfrObservationCodec.build")
        || stack.contains("DecisionBatchBuilder")
        || thread.startsWith("epsilon-encode-")) return "feature_encoding";
    if (stack.contains("FrozenGrpBoundary") || stack.contains(".ai.grp.")) return "grp_boundary";
    if (thread.startsWith("epsilon-decision-stage-")
        || stack.contains("CfrInferenceWorkspace.stage")) return "inference_host_stage";
    if (thread.startsWith("epsilon-decision-submit-")) return "inference_submit";
    if (thread.startsWith("epsilon-decision-complete-")) return "inference_completion";
    if (thread.startsWith("epsilon-inference-") || stack.contains("CfrInferenceCoordinator"))
      return "inference_dispatch";
    if (stack.contains("com.epsilon.engine.")
        || thread.startsWith("epsilon-decision-arena-advance-")) return "engine_advance";
    if (stack.contains("CfrCollector")) return "collector_scheduler";
    if (thread.contains("GC") || thread.contains("G1")) return "gc";
    return "other";
  }

  private static final class Samples {
    final boolean allocation;
    long events, weight, noStack;
    final Map<String, Long> categories = new HashMap<>(),
        threads = new HashMap<>(),
        leaves = new HashMap<>(),
        inclusive = new HashMap<>(),
        classes = new HashMap<>(),
        stacks = new HashMap<>();

    Samples(boolean allocation) {
      this.allocation = allocation;
    }

    void add(String thread, List<String> frames, long amount, String object) {
      events++;
      weight += amount;
      if (frames.isEmpty()) noStack++;
      categories.merge(category(thread, frames), amount, Long::sum);
      threads.merge(thread, amount, Long::sum);
      leaves.merge(frames.isEmpty() ? "<no-stack>" : frames.getFirst(), amount, Long::sum);
      for (String frame : new HashSet<>(frames)) inclusive.merge(frame, amount, Long::sum);
      if (allocation) classes.merge(object, amount, Long::sum);
      List<String> reversed = new ArrayList<>(frames);
      Collections.reverse(reversed);
      String folded =
          thread.replace(';', '_') + ";" + String.join(";", reversed).replace('\n', ' ');
      stacks.merge(folded, amount, Long::sum);
    }

    Map<String, Object> summary() {
      return Map.of(
          "events",
          events,
          "weight",
          weight,
          "weightUnit",
          allocation ? "estimated_heap_bytes" : "samples",
          "noStackEvents",
          noStack,
          "categories",
          top(categories, 100),
          "threads",
          top(threads, 100),
          "leafFrames",
          top(leaves, 60),
          "inclusiveFrames",
          top(inclusive, 100),
          "allocationClasses",
          top(classes, 60));
    }

    String folded() {
      StringBuilder text = new StringBuilder();
      stacks.entrySet().stream()
          .sorted(Map.Entry.comparingByKey())
          .forEach(
              entry ->
                  text.append(entry.getKey()).append(' ').append(entry.getValue()).append('\n'));
      return text.toString();
    }
  }

  private static List<Map<String, Object>> top(Map<String, Long> values, int limit) {
    return values.entrySet().stream()
        .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
        .limit(limit)
        .map(entry -> Map.<String, Object>of("name", entry.getKey(), "weight", entry.getValue()))
        .toList();
  }

  private static String json(Object value) {
    if (value == null) return "null";
    if (value instanceof Number || value instanceof Boolean) return value.toString();
    if (value instanceof Map<?, ?> map)
      return "{"
          + String.join(
              ",",
              map.entrySet().stream()
                  .map(entry -> json(entry.getKey().toString()) + ":" + json(entry.getValue()))
                  .toList())
          + "}";
    if (value instanceof Iterable<?> values) {
      List<String> entries = new ArrayList<>();
      for (Object entry : values) entries.add(json(entry));
      return "[" + String.join(",", entries) + "]";
    }
    StringBuilder result = new StringBuilder("\"");
    for (char ch : value.toString().toCharArray()) {
      if (ch == '"' || ch == '\\') result.append('\\').append(ch);
      else if (ch < 32) result.append(String.format("\\u%04x", (int) ch));
      else result.append(ch);
    }
    return result.append('"').toString();
  }

  private static void selfTest() throws Exception {
    Instant epoch = Instant.EPOCH;
    List<Lifetime> lives = new ArrayList<>();
    for (int group = 0; group < 2; group++)
      for (int lane = 0; lane < 4; lane++)
        lives.add(
            new Lifetime(
                group * 4L + lane,
                WRITER + lane,
                epoch.plusSeconds(group * 10L + lane),
                epoch.plusSeconds(group * 10L + 6 + lane)));
    Window selected = group(lives).getLast();
    if (!selected.start.equals(epoch.plusSeconds(10))
        || !selected.end.equals(epoch.plusSeconds(19))
        || selected.contains(epoch.plusSeconds(5))
        || selected.contains(epoch.plusSeconds(20)))
      throw new AssertionError("Window selection failed");
    Samples samples = new Samples(true);
    samples.add(
        "epsilon-encode-0",
        List.of("com.epsilon.cfr.model.CfrObservationCodec.encodeBuffer"),
        1024,
        "[B");
    samples.add(
        WRITER + "0",
        List.of("com.epsilon.cfr.data.CfrBinaryCodec.writeCompressedEpisode"),
        4096,
        "[B");
    if (samples.weight != 5120
        || samples.categories.get("observation_serialization") != 1024
        || samples.categories.get("episode_persistence") != 4096)
      throw new AssertionError("Allocation weighting failed");
    System.out.println(
        "Window selection, warmup/post-run exclusion, stack classification and allocation weighting"
            + " passed");
  }
}

