package com.epsilon.nano.ai.decision.training;

import com.epsilon.config.settings.DecisionBranchComparisonSettings;
import com.epsilon.config.settings.DecisionTrainArenaSettings;
import com.epsilon.config.settings.DecisionTrainInFlightSpoolSettings;
import com.epsilon.config.settings.DecisionTrainSpoolSettings;
import com.epsilon.config.settings.DeviceSettings;
import com.epsilon.config.settings.SettingsLoader;
import com.epsilon.core.GameState;
import com.epsilon.nano.ai.decision.arena.DecisionAdaptiveExploration;
import com.epsilon.nano.ai.decision.arena.EpsilonDecisionPopulationCollector;
import com.epsilon.nano.ai.decision.data.EpsilonDecisionFragmentStore;
import com.epsilon.nano.ai.decision.data.EpsilonDecisionTrainingTargetIdentity;
import com.epsilon.nano.ai.decision.data.EpsilonDecisionTrajectoryPayloadStore;
import com.epsilon.nano.ai.decision.runtime.EpsilonDecisionEvaluatorFactory;
import com.epsilon.nano.ai.grp.EpsilonGrpTrainingSession;
import com.epsilon.nano.ai.network.NetworkFactory;
import com.epsilon.nano.config.settings.DecisionInferenceSettings;
import com.epsilon.nano.config.settings.DecisionSelectedPgCampaignSettings;
import com.epsilon.nano.config.settings.EpsilonSettings;
import com.epsilon.runtime.DecisionExecutionContext;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;

/** 本番の収集・保存経路だけを、同じ推論器で予熱した後に計測する一時的な測定器。 */
public final class NanoCollectionPersistenceBenchmark {
  private static final long ACTOR = 2L;
  private static final long OPPONENT = 1L;
  private static final Gson JSON = new GsonBuilder().setPrettyPrinting().create();

  private NanoCollectionPersistenceBenchmark() {}

  public static void main(String[] args) throws Exception {
    if (args.length == 2 && args[0].equals("--check-settings")) {
      SettingsLoader config = EpsilonSettings.load(Path.of(args[1]), Map.of());
      System.out.println(JSON.toJson(settings(config)));
      return;
    }
    if (args.length < 4 || args.length > 7)
      throw new IllegalArgumentException(
          "SETTINGS NANO_CHECKPOINT GRP_CHECKPOINT_ROOT OUTPUT"
              + " [GAMES=4096] [WARMUP_GAMES=256] [SEED=20261008]");
    SettingsLoader config = EpsilonSettings.load(Path.of(args[0]), Map.of());
    Path root = Path.of(args[1]).toAbsolutePath().normalize();
    Path checkpoint = EpsilonDecisionCheckpointManager.resolveExistingStrict(root);
    if (checkpoint == null) throw new IOException("Decision checkpoint not found: " + root);
    Path grpRoot = Path.of(args[2]).toAbsolutePath().normalize();
    Path output = Path.of(args[3]).toAbsolutePath().normalize();
    int games = args.length > 4 ? Integer.parseInt(args[4]) : 4096;
    int warmup = args.length > 5 ? Integer.parseInt(args[5]) : 256;
    long seed = args.length > 6 ? Long.parseLong(args[6]) : 20261008L;
    if (games < 1 || warmup < 0) throw new IllegalArgumentException("Invalid game count");
    Files.createDirectories(output.getParent());
    Files.createDirectory(output);
    Files.writeString(output.resolve("effective-settings.json"), JSON.toJson(config.values()));
    var resolved =
        DecisionSelectedPgLearnerContract.resolve(
            config.bind(DecisionSelectedPgCampaignSettings.class), config);
    EpsilonDecisionPopulationCollector.requireSelectedPgActor(resolved.actorRollout());
    var devices = config.bind(DeviceSettings.class);
    Map<String, Object> report = new LinkedHashMap<>();
    report.put("benchmarkVersion", 1);
    report.put("complete", false);
    report.put("checkpointRoot", root.toString());
    report.put("decisionCheckpoint", checkpoint.toString());
    report.put("grpCheckpointRoot", grpRoot.toString());
    report.put("seed", seed);
    report.put("settings", settings(config));
    report.put("javaVersion", System.getProperty("java.version"));
    report.put("availableProcessors", Runtime.getRuntime().availableProcessors());
    report.put("visibleDevices", System.getenv("HIP_VISIBLE_DEVICES"));
    report.put(
        "timingScope",
        "Includes completed hanchan collection, all inference and engine work, frozen GRP,"
            + " configured branches, compressed actor payload writes, completed fragment"
            + " publication, spool.finish, payload writer close/drain, and inference idle wait."
            + " Excludes model load, warmup, report serialization, and post-measurement file"
            + " statistics. Nano's production persistence does not fsync; CFR match publication"
            + " does. No learner or optimizer is constructed, and no checkpoint is changed.");
    report.put(
        "comparisonScope",
        "Nano retains one rotating actor seat per hanchan; CFR retains all four seats. Nano actor"
            + " inference includes policy and value; opponents use policy only. Network requests"
            + " include branches and all evaluated seats; skipped forced opponent actions are not"
            + " counted. Retained actor decisions and network requests are different counters."
            + " Matching seed numbers do not imply matching walls or trajectories across series."
            + " Branch settings match, but branch opportunity and termination rules differ.");
    report.put(
        "adaptiveExplorationScope",
        "Fresh production adaptive-exploration state for each window; warmup calibration is not"
            + " reused by the measured window. Opponents use the production POLICY_GREEDY"
            + " rollout.");
    long setup = System.nanoTime();
    try (var context = new DecisionExecutionContext();
        var actor =
            EpsilonDecisionEvaluatorFactory.openCheckpointEvaluator(checkpoint, context, config);
        var opponent =
            EpsilonDecisionEvaluatorFactory.openPolicyCheckpointEvaluator(
                checkpoint, context, config);
        var grp =
            EpsilonGrpTrainingSession.openInferenceOnly(
                grpRoot, NetworkFactory.getGrpDevices(devices).primary(), config)) {
      report.put("setupSeconds", seconds(setup));
      report.put("actorDevices", actor.devices());
      report.put("opponentDevices", opponent.devices());
      report.put("grpTeacherIdentity", grp.identity());
      if (warmup > 0) {
        report.put(
            "warmup",
            collect(
                config,
                resolved,
                context,
                actor,
                opponent,
                grp,
                output.resolve("warmup-dataset"),
                warmup,
                seed ^ 0x6A09E667F3BCC909L));
        write(output, report);
      }
      report.put(
          "measured",
          collect(
              config,
              resolved,
              context,
              actor,
              opponent,
              grp,
              output.resolve("dataset"),
              games,
              seed));
    }
    report.put("complete", true);
    write(output, report);
    System.out.println(JSON.toJson(report));
  }

  private static Map<String, Object> collect(
      SettingsLoader config,
      DecisionSelectedPgLearnerContract.Resolved resolved,
      DecisionExecutionContext context,
      EpsilonDecisionEvaluatorFactory.Handle actor,
      EpsilonDecisionEvaluatorFactory.Handle opponent,
      EpsilonGrpTrainingSession grp,
      Path dataset,
      int games,
      long seed)
      throws Exception {
    Files.createDirectory(dataset);
    long[][] opponentIds = new long[GameState.NUM_PLAYERS][GameState.NUM_PLAYERS - 1];
    for (long[] ids : opponentIds) Arrays.fill(ids, OPPONENT);
    var identity =
        new EpsilonDecisionFragmentStore.ExpectedIdentity(
            ACTOR,
            grp.identity().iteration(),
            EpsilonDecisionTrainingTargetIdentity.selectedPg(
                resolved.actorRollout().causalTraceLambda(),
                resolved.actorRollout().explorationCreditMix()));
    var exploration = new DecisionAdaptiveExploration(resolved.actorRollout().fullSupport());
    var session = exploration.beginMacro(ACTOR);
    Map<String, Object> result = new LinkedHashMap<>();
    context.awaitInferenceIdle();
    context.resetInferenceMetrics();
    try (var payloads =
        EpsilonDecisionTrajectoryPayloadStore.fromSettings(
            dataset, true, config.bind(DecisionTrainInFlightSpoolSettings.class))) {
      var spool =
          EpsilonDecisionTrainFragmentPipeline.openSpool(
              dataset, identity, config.bind(DecisionTrainSpoolSettings.class));
      long started = System.nanoTime();
      int[] completed = {0};
      boolean collected = false;
      EpsilonDecisionTrainFragmentPipeline.TrainCollection collection;
      try {
        var metrics =
            EpsilonDecisionPopulationCollector.collect(
                EpsilonDecisionPopulationCollector.Request.standard(
                        games,
                        seed,
                        actor.evaluator(),
                        ACTOR,
                        opponentIds,
                        ignored -> opponent.evaluator(),
                        resolved.actorRollout(),
                        resolved.opponentRollout(),
                        (index, gameSeed, game) -> {
                          spool.accept(index, gameSeed, game);
                          completed[0]++;
                        },
                        payloads)
                    .withGrpInference(grp.inference())
                    .withAdaptiveExploration(session),
                config);
        result.put("arenaMetrics", metrics);
        result.put("requestedNetworkDecisions", metrics.inferenceRequestCount());
        result.put("adaptiveExploration", exploration.completeMacro(session));
        collected = true;
      } finally {
        if (!collected) exploration.abortMacro(session);
        collection = spool.finish().withTrajectoryPayloadFiles(payloads.payloadFiles());
      }
      payloads.close();
      context.awaitInferenceIdle();
      double elapsed = seconds(started);
      if (completed[0] != games || collection.fragmentCount() != games)
        throw new IllegalStateException("Not all requested hanchan were persisted");
      result.put("dataset", dataset.toString());
      result.put("seed", seed);
      result.put("completedGames", completed[0]);
      result.put("fragmentCount", collection.fragmentCount());
      result.put("retainedActorDecisions", collection.samples());
      result.put("elapsedSeconds", elapsed);
      result.put("gamesPerSecond", games / elapsed);
      result.put("retainedActorDecisionsPerSecond", collection.samples() / elapsed);
      result.put(
          "networkRequestsPerSecond",
          ((Number) result.get("requestedNetworkDecisions")).longValue() / elapsed);
      result.put("deviceMetrics", context.inferenceMetrics());
      result.put("dispatchMetrics", context.inferenceDispatchMetrics());
      long bytes = 0;
      for (Path path : collection.fragmentPaths()) bytes = Math.addExact(bytes, Files.size(path));
      for (Path path : collection.trajectoryPayloadFiles())
        bytes = Math.addExact(bytes, Files.size(path));
      result.put("persistedBytes", bytes);
      return result;
    }
  }

  private static Map<String, Object> settings(SettingsLoader config) {
    return Map.of(
        "devices", config.bind(DeviceSettings.class),
        "inference", config.bind(DecisionInferenceSettings.class),
        "arena", config.bind(DecisionTrainArenaSettings.class),
        "branches", config.bind(DecisionBranchComparisonSettings.class),
        "payloadSpool", config.bind(DecisionTrainInFlightSpoolSettings.class),
        "fragmentSpool", config.bind(DecisionTrainSpoolSettings.class));
  }

  private static void write(Path output, Map<String, Object> report) throws IOException {
    Files.writeString(output.resolve("report.json"), JSON.toJson(report) + System.lineSeparator());
  }

  private static double seconds(long started) {
    return (System.nanoTime() - started) / 1_000_000_000.0;
  }
}

